// Step 1: Validate Configuration
int config_valid = 1;
if (sa_config.enter_rad >= sa_config.exit_rad ||
    sa_config.enter_rad < 0.0 || sa_config.exit_rad > PI ||
    sa_config.acquire_gain_nm_rad < 0.0 ||
    sa_config.track_gain_nm_rad < 0.0 ||
    sa_config.torque_limit_nm <= 0.0 ||
    sa_config.max_slew_nm_per_cycle < 0.0 ||
    sa_config.coast_decay < 0.0 || sa_config.coast_decay > 1.0 ||
    sa_config.acquire_samples < 1 || sa_config.acquire_samples > 20 ||
    sa_config.max_coast_samples < 1 ||
    sa_config.max_bad_samples <= sa_config.max_coast_samples ||
    sa_config.max_bad_samples > 20) {
    config_valid = 0;
}

// Step 2: Validate Inputs
int input_valid = 1;
if (!sa_input.valid) {
    input_valid = 0;
}

const adcs_vec3_t *meas = sa_input.measured_body;
const adcs_vec3_t *target = sa_input.target_body;

if (config_valid) {
    if (meas == NULL || target == NULL ||
        !adcs_is_finite_vec3(meas) || !adcs_is_finite_vec3(target)) {
        input_valid = 0;
    } else {
        double m_norm = adcs_vec3_norm(meas);
        double t_norm = adcs_vec3_norm(target);
        if (m_norm < ADCS_EPS_NORM || t_norm < ADCS_EPS_NORM) {
            input_valid = 0;
        }
    }
}

int rejected = (!config_valid) || (!input_valid);

// Step 3: Handle Rejected Samples
if (rejected) {
    sa_state.good_samples = 0;
    sa_state.bad_samples++;

    // If we are in COAST, we absorb the rejection
    if (sa_state.mode == SA_COAST && config_valid) {
        // Remain in COAST
        // Publish decayed torque
        adcs_vec3_t coast_torque = adcs_vec3_scale(&sa_state.previous_torque_nm, sa_config.coast_decay);

        // Apply Slew Limit
        double prev_tx = sa_state.previous_torque_nm.x;
        double prev_ty = sa_state.previous_torque_nm.y;
        double prev_tz = sa_state.previous_torque_nm.z;
        double max_slew = sa_config.max_slew_nm_per_cycle;

        double tx = coast_torque.x;
        double ty = coast_torque.y;
        double tz = coast_torque.z;

        unint32 slew_mask = 0;

        double dx = tx - prev_tx;
        if (dx > max_slew) { tx = prev_tx + max_slew; slew_mask |= 1U; }
        else if (dx < -max_slew) { tx = prev_tx - max_slew; slew_mask |= 1U; }

        double dy = ty - prev_ty;
        if (dy > max_slew) { ty = prev_ty + max_slew; slew_mask |= (1U<<1); }
        else if (dy < -max_slew) { ty = prev_ty - max_slew; slew_mask |= (1U<<1); }

        double dz = tz - prev_tz;
        if (dz > max_slew) { tz = prev_tz + max_slew; slew_mask |= (1U<<2); }
        else if (dz < -max_slew) { tz = prev_tz - max_slew; slew_mask |= (1U<<2); }

        sa_output.torque_nm.x = tx;
        sa_output.torque_nm.y = ty;
        sa_output.torque_nm.z = tz;
        sa_output.slew_mask = slew_mask;

        sa_state.previous_torque_nm.x = tx;
        sa_state.previous_torque_nm.y = ty;
        sa_state.previous_torque_nm.z = tz;

        sa_output.mode = SA_COAST;
        sa_state.coast_samples++;
        sa_output.error_rad = 0.0;
        sa_output.rotation_axis = (adcs_vec3_t){0,0,0};

        // Check Fault
        if (sa_state.bad_samples >= sa_config.max_bad_samples) {
            sa_output.mode = SA_FAULT;
        }
        return;
    }

    // If not in COAST (or config invalid preventing COAST absorption)
    if (sa_state.bad_samples >= sa_config.max_bad_samples) {
        sa_output.mode = SA_FAULT;
    } else {
        sa_output.mode = sa_state.mode;
    }

    // Output zero torque for non-coast rejection
    sa_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.slew_mask = 0;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0,0,0};

    return;
}

// Step 4: Accepted Sample Processing
sa_state.good_samples++;
if (sa_state.mode != SA_COAST) {
    sa_state.coast_samples = 0;
}

// Normalize vectors
adcs_vec3_t meas_n, target_n;
adcs_vec3_normalize(meas, ADCS_EPS_NORM, &meas_n);
adcs_vec3_normalize(target, ADCS_EPS_NORM, &target_n);

// Compute Angle and Axis
double dot = adcs_vec3_dot(&meas_n, &target_n);
adcs_vec3_t cross = adcs_vec3_cross(&meas_n, &target_n);
double norm_cross = adcs_vec3_norm(&cross);

double angle = atan2(norm_cross, dot);
adcs_vec3_t axis = cross; 

// Antiparallel handling
if (norm_cross < ADCS_EPS_COLLINEAR) {
    if (dot < -0.999999) { 
        double align[3] = {fabs(meas_n.x), fabs(meas_n.y), fabs(meas_n.z)};
        int min_idx = 0;
        if (align[1] < align[min_idx]) min_idx = 1;
        if (align[2] < align[min_idx]) min_idx = 2;

        adcs_vec3_t basis = {(min_idx==0)?1.0:0.0, (min_idx==1)?1.0:0.0, (min_idx==2)?1.0:0.0};
        axis = adcs_vec3_cross(&meas_n, &basis);
        double ax_norm = adcs_vec3_norm(&axis);
        if (ax_norm > ADCS_EPS_NORM) {
            axis = adcs_vec3_scale(&axis, 1.0 / ax_norm);
        } else {
            axis = (adcs_vec3_t){1,0,0};
        }
        angle = PI;
    }
}

// Determine New Mode
sa_mode_t next_mode = sa_state.mode;

if (sa_state.mode == SA_OFF) {
    next_mode = SA_SEARCH;
} else if (sa_state.mode == SA_SEARCH) {
    if (angle <= sa_config.enter_rad) {
        next_mode = SA_ACQUIRE;
        sa_state.good_samples = 1;
    }
} else if (sa_state.mode == SA_ACQUIRE) {
    if (angle <= sa_config.enter_rad) {
        sa_state.good_samples++;
        if (sa_state.good_samples >= sa_config.acquire_samples) {
            next_mode = SA_TRACK;
        }
    } else {
        next_mode = SA_SEARCH;
        sa_state.good_samples = 0;
    }
} else if (sa_state.mode == SA_TRACK) {
    if (angle >= sa_config.exit_rad) {
        next_mode = SA_SEARCH;
    }
} else if (sa_state.mode == SA_COAST) {
    if (angle < sa_config.exit_rad) {
        next_mode = SA_TRACK;
    } else {
        next_mode = SA_SEARCH;
    }
}

sa_state.mode = next_mode;

// Calculate Torque
double gain;
if (next_mode == SA_TRACK) {
    gain = sa_config.track_gain_nm_rad;
} else {
    gain = sa_config.acquire_gain_nm_rad;
}

adcs_vec3_t raw_torque = adcs_vec3_scale(&axis, gain * angle);

// Limit Magnitude
double mag = adcs_vec3_norm(&raw_torque);
if (mag > sa_config.torque_limit_nm) {
    double scale = sa_config.torque_limit_nm / mag;
    raw_torque = adcs_vec3_scale(&raw_torque, scale);
}

// Limit Slew
double prev_tx = sa_state.previous_torque_nm.x;
double prev_ty = sa_state.previous_torque_nm.y;
double prev_tz = sa_state.previous_torque_nm.z;

double tx = raw_torque.x;
double ty = raw_torque.y;
double tz = raw_torque.z;

unint32 slew_mask = 0;
double max_slew = sa_config.max_slew_nm_per_cycle;

double dx = tx - prev_tx;
if (dx > max_slew) { tx = prev_tx + max_slew; slew_mask |= 1U; }
else if (dx < -max_slew) { tx = prev_tx - max_slew; slew_mask |= 1U; }

double dy = ty - prev_ty;
if (dy > max_slew) { ty = prev_ty + max_slew; slew_mask |= (1U<<1); }
else if (dy < -max_slew) { ty = prev_ty - max_slew; slew_mask |= (1U<<1); }

double dz = tz - prev_tz;
if (dz > max_slew) { tz = prev_tz + max_slew; slew_mask |= (1U<<2); }
else if (dz < -max_slew) { tz = prev_tz - max_slew; slew_mask |= (1U<<2); }

sa_output.torque_nm.x = tx;
sa_output.torque_nm.y = ty;
sa_output.torque_nm.z = tz;
sa_output.slew_mask = slew_mask;
sa_output.rotation_axis = axis;
sa_output.error_rad = angle;

// Update State
sa_state.previous_torque_nm.x = tx;
sa_state.previous_torque_nm.y = ty;
sa_state.previous_torque_nm.z = tz;

sa_output.mode = next_mode;

