// 1. Configuration and Input Validation
int config_valid = 1;

// Check configuration constraints
if (sa_config.enter_rad < 0.0 || sa_config.exit_rad < 0.0 || 
    sa_config.enter_rad > sa_config.exit_rad || sa_config.exit_rad > ADCS_PI ||
    sa_config.acquire_gain_nm_rad < 0.0 || sa_config.track_gain_nm_rad < 0.0 ||
    sa_config.torque_limit_nm <= 0.0 || sa_config.max_slew_nm_per_cycle <= 0.0 ||
    sa_config.coast_decay < 0.0 || sa_config.coast_decay > 1.0 ||
    sa_config.acquire_samples < 1 || sa_config.acquire_samples > 20 ||
    sa_config.max_coast_samples < 1 || sa_config.max_bad_samples < 2 ||
    sa_config.max_coast_samples >= sa_config.max_bad_samples || 
    sa_config.max_bad_samples > 20) {
    config_valid = 0;
}

// Check input validity
int input_valid = 1;
if (!config_valid) {
    input_valid = 0;
} else if (!sa_input.enable || !sa_input.valid) {
    input_valid = 0;
} else if (sa_input.measured_body == NULL || sa_input.target_body == NULL) {
    input_valid = 0;
} else if (!adcs_is_finite_vec3(sa_input.measured_body) || !adcs_is_finite_vec3(sa_input.target_body)) {
    input_valid = 0;
} else {
    adcs_vec3_t m_check, t_check;
    if (adcs_vec3_normalize(sa_input.measured_body, ADCS_EPS_NORM, &m_check) != ADCS_OK) {
        input_valid = 0;
    } else if (adcs_vec3_normalize(sa_input.target_body, ADCS_EPS_NORM, &t_check) != ADCS_OK) {
        input_valid = 0;
    } else {
        /* Normalization successful */
    }
}

int rejected_sample = !input_valid;

// Handle Fault State
if (sa_state.mode == SA_FAULT) {
    sa_output.mode = SA_FAULT;
    sa_output.error_rad = 0.0;
    sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
    sa_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    sa_output.slew_mask = 0;
    return;
}

// Determine effective mode for logic (OFF -> SEARCH)
sa_mode_t current_mode = sa_state.mode;
if (current_mode == SA_OFF) {
    current_mode = SA_SEARCH;
}

// Initialize outputs
sa_output.mode = current_mode;
sa_output.error_rad = 0.0;
sa_output.rotation_axis = (adcs_vec3_t){0, 0, 0};
sa_output.torque_nm = (adcs_vec3_t){0, 0, 0};
sa_output.slew_mask = 0U;

