uint32_t next_good = 0;
uint32_t next_bad = 0;
uint32_t next_coast = 0;

if (current_mode == SA_SEARCH) {
    if (error_rad <= sa_config.enter_rad) {
        next_mode = SA_ACQUIRE;
        next_good = 1;
    } else {
        next_mode = SA_SEARCH;
        next_good = 0;
    }
    next_coast = 0;
} 
else if (current_mode == SA_ACQUIRE) {
    if (error_rad <= sa_config.enter_rad) {
        next_good = sa_state.good_samples + 1;
        if (next_good >= sa_config.acquire_samples) {
            next_mode = SA_TRACK;
            next_good = 0; 
        } else {
            next_mode = SA_ACQUIRE;
        }
        next_coast = 0;
    } else {
        // Leaving window
        next_mode = SA_SEARCH;
        next_good = 0;
        next_coast = 0;
    }
}
else if (current_mode == SA_TRACK) {
    if (error_rad >= sa_config.exit_rad) {
        next_mode = SA_SEARCH;
        next_good = 0;
    } else {
        next_mode = SA_TRACK;
        next_good = 0; 
    }
    next_coast = 0;
}
else if (current_mode == SA_COAST) {
    // Valid COAST sample
    if (error_rad < sa_config.exit_rad) {
        next_mode = SA_TRACK;
    } else {
        next_mode = SA_SEARCH;
    }
    next_coast = 0; 
    next_good = 0;
}
else if (current_mode == SA_FAULT) {
    next_mode = SA_FAULT;
    next_good = 0;
}
else {
    // Defensive fallback for Rule 15.7 compliance
    next_mode = current_mode;
    next_good = 0;
    next_coast = 0;
}

